import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # Ensure target_positions has the right structure
    if target_positions.empty:
        target_positions = pd.DataFrame(columns=["account_id", "symbol", "qty", "price", "row_version"])

    # Ensure position_events has the right structure
    if position_events.empty:
        position_events = pd.DataFrame(columns=["batch_seq", "account_id", "symbol", "op", "qty", "price", "row_version"])

    # Step 1: Deduplicate events by batch_seq (keep first occurrence)
    position_events = position_events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Step 2: Apply replay guard
    # For each key (account_id, symbol) that exists in target_positions,
    # filter out events with row_version <= target's row_version
    target_dict = {}
    if not target_positions.empty:
        for _, row in target_positions.iterrows():
            key = (row["account_id"], row["symbol"])
            target_dict[key] = row["row_version"]

    filtered_events = []
    for _, event in position_events.iterrows():
        key = (event["account_id"], event["symbol"])
        if key in target_dict:
            if event["row_version"] > target_dict[key]:
                filtered_events.append(event)
        else:
            # No row in target, so no guard
            filtered_events.append(event)

    if filtered_events:
        position_events = pd.DataFrame(filtered_events)
    else:
        position_events = pd.DataFrame(columns=["batch_seq", "account_id", "symbol", "op", "qty", "price", "row_version"])

    # Step 3: Sort events by row_version, then batch_seq
    if not position_events.empty:
        position_events = position_events.sort_values(["row_version", "batch_seq"]).reset_index(drop=True)

    # Step 4: Build working state from target_positions
    state = {}
    if not target_positions.empty:
        for _, row in target_positions.iterrows():
            key = (row["account_id"], row["symbol"])
            state[key] = {
                "qty": row["qty"],
                "price": row["price"],
                "row_version": row["row_version"]
            }

    closed_positions_dict = {}

    # Step 5: Apply events in order
    if not position_events.empty:
        for _, event in position_events.iterrows():
            key = (event["account_id"], event["symbol"])
            op = event["op"]
            event_qty = event["qty"]
            event_price = event["price"]
            event_version = event["row_version"]

            exists = key in state

            if op == "D":
                # Delete: remove the row if it exists
                if exists:
                    del state[key]
                    closed_positions_dict[key] = event_version
            elif op == "I" or op == "U":
                # Check if qty == 0 (close position)
                is_close = pd.isna(event_qty) or event_qty == 0

                if is_close:
                    # Close position: remove it like 'D'
                    if exists:
                        del state[key]
                        closed_positions_dict[key] = event_version
                else:
                    # Regular I or U
                    if exists:
                        # Update existing row
                        state[key]["qty"] = event_qty
                        # For 'U' with NULL price, keep existing price
                        if op == "U" and pd.isna(event_price):
                            # Keep existing price
                            pass
                        else:
                            state[key]["price"] = event_price
                        state[key]["row_version"] = event_version
                    else:
                        # Create new row
                        state[key] = {
                            "qty": event_qty,
                            "price": event_price,
                            "row_version": event_version
                        }

    # Step 6: Build new_positions from state
    new_positions_rows = []
    for (account_id, symbol), data in state.items():
        new_positions_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "qty": data["qty"],
            "price": data["price"],
            "row_version": data["row_version"]
        })

    if new_positions_rows:
        new_positions = pd.DataFrame(new_positions_rows)
        new_positions = new_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })
    else:
        new_positions = pd.DataFrame(columns=["account_id", "symbol", "qty", "price", "row_version"])
        new_positions = new_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })

    # Step 7: Build closed_positions
    closed_rows = []
    for (account_id, symbol), closed_version in closed_positions_dict.items():
        closed_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "closed_version": closed_version
        })

    if closed_rows:
        closed_positions = pd.DataFrame(closed_rows)
        closed_positions = closed_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "closed_version": "int64"
        })
    else:
        closed_positions = pd.DataFrame(columns=["account_id", "symbol", "closed_version"])
        closed_positions = closed_positions.astype({
            "account_id": "int64",
            "symbol": "str",
            "closed_version": "int64"
        })

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions
    }
